    "content": "import React, { useState, useEffect, useRef } from 'react';
import {
  IonPage, IonContent, IonList, IonItem, IonLabel, IonButton, IonIcon,
  IonModal, IonInput, IonTextarea, IonToggle, IonFab, IonFabButton,
  IonSearchbar, IonLoading, IonToast, IonAlert, IonInfiniteScroll,
  IonInfiniteScrollContent, IonNote
} from '@ionic/react';
import { addOutline, createOutline, trashOutline, searchOutline, closeOutline } from 'ionicons/icons';
import { useIonViewWillEnter } from '@ionic/react';
import { useUser } from '../contexts/UserContext';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { Supplier, getAllSuppliers, createSupplier, updateSupplier, deleteSupplier } from '../api/supplierApi';

const PAGE_SIZE = 20;

const toHermosillo = (utc: string | undefined | null): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  // Convert to Hermosillo (UTC-7)
  const hermosilloTime = new Date(d.getTime() - 7 * 60 * 60 * 1000);
  return hermosilloTime.toLocaleString('es-MX', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true });
};

const SupplierPage: React.FC = () => {
  const { companyId } = useUser();
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [filteredSuppliers, setFilteredSuppliers] = useState<Supplier[]>([]);
  const [displayedSuppliers, setDisplayedSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [editingSupplier, setEditingSupplier] = useState<Supplier | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [supplierToDelete, setSupplierToDelete] = useState<Supplier | null>(null);

  const [formState, setFormState] = useState<Omit<Supplier, 'supplierId' | 'created_At' | 'updated_at'>>({
    companyId: companyId,
    supplierName: '',
    contactName: '',
    phone: '',
    email: '',
    address: '',
    active: '1',
  });

  const infiniteScrollRef = useRef<HTMLIonInfiniteScrollElement>(null);

  const [popoverState, setPopoverState] = useState<{ 
    showAlertPopover: boolean; 
    showMailPopover: boolean; 
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const fetchSuppliers = async (clearExisting = false) => {
    if (loading) return;
    setLoading(true);
    setError(null);
    try {
      const data = await getAllSuppliers(companyId);
      setSuppliers(data);
      if (clearExisting) {
        setDisplayedSuppliers([]);
        infiniteScrollRef.current?.complete();
      }
    } catch (err) {
      setError((err as Error).message || 'Error al cargar proveedores.');
    } finally {
      setLoading(false);
    }
  };

  useIonViewWillEnter(() => {
    fetchSuppliers(true);
  });

  useEffect(() => {
    const lowercasedSearchTerm = searchTerm.toLowerCase();
    const currentFiltered = suppliers.filter(supplier =>
      supplier.supplierName.toLowerCase().includes(lowercasedSearchTerm) ||
      (supplier.contactName?.toLowerCase().includes(lowercasedSearchTerm)) ||
      (supplier.email?.toLowerCase().includes(lowercasedSearchTerm))
    );
    setFilteredSuppliers(currentFiltered);
    setDisplayedSuppliers(currentFiltered.slice(0, PAGE_SIZE));
    if (infiniteScrollRef.current) {
      infiniteScrollRef.current.disabled = currentFiltered.length <= PAGE_SIZE;
    }
  }, [searchTerm, suppliers]);

  const loadMoreItems = (event: CustomEvent<void>) => {
    const currentLength = displayedSuppliers.length;
    const nextChunk = filteredSuppliers.slice(currentLength, currentLength + PAGE_SIZE);
    setDisplayedSuppliers(prev => [...prev, ...nextChunk]);
    (event.target as HTMLIonInfiniteScrollElement).complete();

    if (displayedSuppliers.length + nextChunk.length >= filteredSuppliers.length) {
      (event.target as HTMLIonInfiniteScrollElement).disabled = true;
    }
  };

  const handleAddSupplier = () => {
    setEditingSupplier(null);
    setFormState({
      companyId: companyId,
      supplierName: '',
      contactName: '',
      phone: '',
      email: '',
      address: '',
      active: '1',
    });
    setShowModal(true);
  };

  const handleEditSupplier = (supplier: Supplier) => {
    setEditingSupplier(supplier);
    setFormState({
      companyId: supplier.companyId,
      supplierName: supplier.supplierName,
      contactName: supplier.contactName,
      phone: supplier.phone,
      email: supplier.email,
      address: supplier.address,
      active: supplier.active,
    });
    setShowModal(true);
  };

  const handleSaveSupplier = async () => {
    if (!formState.supplierName) {
      setError('El nombre del proveedor es obligatorio.');
      return;
    }
    setSaving(true);
    setError(null);
    try {
      if (editingSupplier) {
        await updateSupplier(editingSupplier.supplierId, formState);
        setError('Proveedor actualizado exitosamente.');
      } else {
        await createSupplier(formState);
        setError('Proveedor creado exitosamente.');
      }
      setShowModal(false);
      fetchSuppliers(true);
    } catch (err) {
      setError((err as Error).message || 'Error al guardar el proveedor.');
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteClick = (supplier: Supplier) => {
    setSupplierToDelete(supplier);
    setShowDeleteAlert(true);
  };

  const confirmDeleteSupplier = async () => {
    if (supplierToDelete) {
      setLoading(true);
      setError(null);
      try {
        await deleteSupplier(supplierToDelete.supplierId, companyId);
        setError('Proveedor eliminado exitosamente.');
        fetchSuppliers(true);
      } catch (err) {
        setError((err as Error).message || 'Error al eliminar el proveedor.');
      } finally {
        setLoading(false);
        setSupplierToDelete(null);
      }
    }
  };

  return (
    <IonPage className="supplier-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Proveedores — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonSearchbar
          className="supplier-searchbar"
          value={searchTerm}
          onIonInput={(e: CustomEvent<InputInputEventDetail>) => setSearchTerm(e.detail.value!)}
          placeholder="Buscar proveedores"
          debounce={300}
        />

        <IonList className="supplier-list">
          {displayedSuppliers.map(supplier => (
            <IonItem key={supplier.supplierId} className="supplier-item">
              <IonLabel>
                <h2>{supplier.supplierName}</h2>
                <p>Contacto: {supplier.contactName || 'N/A'}</p>
                <p>Teléfono: {supplier.phone || 'N/A'}</p>
                <p>Email: {supplier.email || 'N/A'}</p>
                <IonNote slot="end" color={supplier.active === '1' ? 'success' : 'medium'}>
                  {supplier.active === '1' ? 'Activo' : 'Inactivo'}
                </IonNote>
                <p className="supplier-date-info">Creado: {toHermosillo(supplier.created_At)}</p>
                {supplier.updated_at && <p className="supplier-date-info">Actualizado: {toHermosillo(supplier.updated_at)}</p>}
              </IonLabel>
              <IonButtons slot="end">
                <IonButton onClick={() => handleEditSupplier(supplier)}>
                  <IonIcon icon={createOutline} color="primary" />
                </IonButton>
                <IonButton color="danger" onClick={() => handleDeleteClick(supplier)}>
                  <IonIcon icon={trashOutline} />
                </IonButton>
              </IonButtons>
            </IonItem>
          ))}
        </IonList>

        <IonInfiniteScroll
          onIonInfinite={(ev: CustomEvent<void>) => loadMoreItems(ev)}
          threshold="100px"
          ref={infiniteScrollRef}
          disabled={displayedSuppliers.length === filteredSuppliers.length}
        >
          <IonInfiniteScrollContent loadingText="Cargando más proveedores..."></IonInfiniteScrollContent>
        </IonInfiniteScroll>

        <IonFab vertical="bottom" horizontal="end" slot="fixed" className="supplier-fab">
          <IonFabButton onClick={handleAddSupplier}>
            <IonIcon icon={addOutline} />
          </IonFabButton>
        </IonFab>

        <IonModal isOpen={showModal} onDidDismiss={() => setShowModal(false)} className="supplier-modal">
          <Header
            screenTitle={editingSupplier ? "Editar Proveedor" : "Nuevo Proveedor"}
            presentAlertPopover={() => { /* no-op for modal header */ }}
            presentMailPopover={() => { /* no-op for modal header */ }}
            onClose={() => setShowModal(false)}
          />
          <IonContent className="ion-padding">
            <div className="supplier-form-field">
              <IonInput
                fill="outline"
                label="Nombre del Proveedor *"
                labelPlacement="floating"
                value={formState.supplierName}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, supplierName: e.detail.value! }))}
                className={!formState.supplierName ? 'ion-invalid ion-touched' : ''}
                errorText="El nombre es obligatorio"
              />
            </div>
            <div className="supplier-form-field">
              <IonInput
                fill="outline"
                label="Nombre de Contacto"
                labelPlacement="floating"
                value={formState.contactName}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, contactName: e.detail.value || null }))}
              />
            </div>
            <div className="supplier-form-field">
              <IonInput
                fill="outline"
                label="Teléfono"
                labelPlacement="floating"
                type="tel"
                value={formState.phone}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, phone: e.detail.value || null }))}
              />
            </div>
            <div className="supplier-form-field">
              <IonInput
                fill="outline"
                label="Email"
                labelPlacement="floating"
                type="email"
                value={formState.email}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, email: e.detail.value || null }))}
              />
            </div>
            <div className="supplier-form-field">
              <IonTextarea
                fill="outline"
                label="Dirección"
                labelPlacement="floating"
                value={formState.address}
                onIonInput={(e: CustomEvent<TextareaInputEventDetail>) => setFormState(p => ({ ...p, address: e.detail.value || null }))}
                rows={3}
              />
            </div>
            <IonItem className="supplier-toggle-item">
              <IonLabel>Activo</IonLabel>
              <IonToggle
                checked={formState.active === '1'}
                onIonChange={(e: CustomEvent<ToggleChangeEventDetail>) => setFormState(p => ({ ...p, active: e.detail.checked ? '1' : '0' }))}
              />
            </IonItem>
            <IonButton expand="block" onClick={handleSaveSupplier} disabled={saving || !formState.supplierName}>
              {saving ? 'Guardando...' : 'Guardar'}
            </IonButton>
          </IonContent>
        </IonModal>

        <IonLoading isOpen={loading} message={'Cargando proveedores...'} />
        <IonToast
          isOpen={!!error}
          message={error}
          duration={3000}
          onDidDismiss={() => setError(null)}
          color={error?.includes('Error') ? 'danger' : 'success'}
        />

        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header={'Confirmar Eliminación'}
          message={`¿Estás seguro de que quieres eliminar al proveedor "${supplierToDelete?.supplierName}"?`}
          buttons={[
            { text: 'Cancelar', role: 'cancel' },
